def rule_fit(din_,dout_,v,wrap,mode,tol,mark):
    R,C=len(din_),len(din_[0]); B=blocks(din_); _,E,T=analyze(din_,dout_)
    def ov(p,q):
        dr,dj=abs(p[0]-q[0]),abs(p[1]-q[1])
        return (dr==0 and dj==0) if tol==0 else (dr<=tol and dj<=tol)
    def sh(p,s):
        r,c=p[0]+s*v[0],p[1]+s*v[1]
        if wrap in ('r','both'): r%=R
        if wrap in ('c','both'): c%=C
        return (r,c)
    S=set()
    for p in B:
        cand=[]
        if mark in ('src','both'):
            cand += [sh(p,1)] + ([sh(p,-1)] if mode=='sym' else [])
        if mark in ('tgt','both'):
            cand += [sh(p,-1)] + ([sh(p,1)] if mode=='sym' else [])
